"""Versioned episode workflows; original object, media, decisions and run authority."""
from sqlalchemy import Table,Column,Text,Integer,DateTime,ForeignKeyConstraint,PrimaryKeyConstraint,UniqueConstraint,CheckConstraint,Index,text
from sqlalchemy.dialects.postgresql import UUID,JSONB

INTELLIGENT_TABLES=('intelligent_definitions','intelligent_workflows','intelligent_versions','intelligent_assets','intelligent_units','intelligent_dependencies','intelligent_media','intelligent_runs','intelligent_tasks','intelligent_decisions')
INTELLIGENT_IMMUTABLE=tuple(n for n in INTELLIGENT_TABLES if n!='intelligent_tasks')


def install_intelligent_schema(metadata):
    def uid(name,**kw):return Column(name,UUID(as_uuid=False),**kw)
    def stamp():return Column('created_at',DateTime(timezone=True),nullable=False,server_default=text('now()'))
    def table(name,*cols):return Table(name,metadata,uid('project_id',nullable=False),*cols,ForeignKeyConstraint(['project_id'],['projects.id']))
    def ref(local,target):return ForeignKeyConstraint(['project_id',local],[target+'.project_id',target+'.id'])
    definitions=table('intelligent_definitions',uid('id',nullable=False),Column('key',Text,nullable=False),Column('version',Integer,nullable=False),uid('artifact_id',nullable=False),PrimaryKeyConstraint('project_id','id'),UniqueConstraint('project_id','key','version'),ref('artifact_id','artifact_versions'))
    workflows=table('intelligent_workflows',uid('id',nullable=False),uid('episode_id',nullable=False),uid('definition_id',nullable=False),Column('title',Text,nullable=False),Column('created_by',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),ref('episode_id','episodes'),ref('definition_id','intelligent_definitions'))
    versions=table('intelligent_versions',uid('id',nullable=False),uid('workflow_id',nullable=False),Column('version',Integer,nullable=False),uid('parent_id'),uid('artifact_id',nullable=False),uid('source_artifact_id'),uid('template_artifact_id'),Column('route',Text,nullable=False),Column('blocking_mode',Text,nullable=False),Column('unit_count',Integer,nullable=False),Column('asset_count',Integer,nullable=False),Column('dependency_count',Integer,nullable=False),Column('media_count',Integer,nullable=False),Column('created_by',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),UniqueConstraint('project_id','workflow_id','version'),UniqueConstraint('project_id','workflow_id','id'),ref('workflow_id','intelligent_workflows'),ref('artifact_id','artifact_versions'),ref('source_artifact_id','artifact_versions'),ref('template_artifact_id','artifact_versions'),ForeignKeyConstraint(['project_id','workflow_id','parent_id'],['intelligent_versions.project_id','intelligent_versions.workflow_id','intelligent_versions.id']),CheckConstraint("route IN ('creation','storyboard','storyboard_video','multi_reference_video') AND blocking_mode IN ('2d','3d','skip')",name='route'),CheckConstraint('version>0 AND unit_count BETWEEN 0 AND 200 AND asset_count BETWEEN 0 AND 200 AND dependency_count BETWEEN 0 AND 1000 AND media_count BETWEEN 0 AND 2000',name='counts'))
    assets=table('intelligent_assets',uid('version_id',nullable=False),Column('asset_key',Text,nullable=False),uid('asset_id',nullable=False),uid('spec_id',nullable=False),Column('ordinal',Integer,nullable=False),PrimaryKeyConstraint('project_id','version_id','asset_key'),ref('version_id','intelligent_versions'),ref('asset_id','asset_identities'),ref('spec_id','asset_spec_versions'))
    units=table('intelligent_units',uid('version_id',nullable=False),Column('unit_key',Text,nullable=False),Column('kind',Text,nullable=False),Column('ordinal',Integer,nullable=False),Column('title',Text,nullable=False),Column('description',Text,nullable=False),Column('duration_ms',Integer,nullable=False),Column('segments',JSONB,nullable=False),Column('skip_reason',Text,nullable=False),Column('lineart_purpose',Text,nullable=False),uid('shot_id'),uid('spatial_version_id'),PrimaryKeyConstraint('project_id','version_id','unit_key'),UniqueConstraint('project_id','version_id','ordinal'),ref('version_id','intelligent_versions'),ref('shot_id','shots'),ref('spatial_version_id','spatial_scene_versions'),CheckConstraint("kind IN ('blocking','shot') AND lineart_purpose IN ('none','reference_image','first_frame') AND duration_ms BETWEEN 1 AND 3600000 AND ordinal>=0",name='shape'))
    dependencies=table('intelligent_dependencies',uid('version_id',nullable=False),Column('unit_key',Text,nullable=False),uid('source_version_id',nullable=False),Column('source_unit_key',Text,nullable=False),Column('purpose',Text,nullable=False),PrimaryKeyConstraint('project_id','version_id','unit_key','source_version_id','source_unit_key'),ForeignKeyConstraint(['project_id','version_id','unit_key'],['intelligent_units.project_id','intelligent_units.version_id','intelligent_units.unit_key']),ForeignKeyConstraint(['project_id','source_version_id','source_unit_key'],['intelligent_units.project_id','intelligent_units.version_id','intelligent_units.unit_key']),CheckConstraint("purpose IN ('anchor','blocking') AND NOT (version_id=source_version_id AND unit_key=source_unit_key)",name='edge'))
    media=table('intelligent_media',uid('version_id',nullable=False),Column('unit_key',Text,nullable=False),Column('purpose',Text,nullable=False),uid('media_id',nullable=False),uid('decision_id',nullable=False),uid('spatial_export_id'),PrimaryKeyConstraint('project_id','version_id','unit_key','purpose','media_id'),ForeignKeyConstraint(['project_id','version_id','unit_key'],['intelligent_units.project_id','intelligent_units.version_id','intelligent_units.unit_key']),ref('media_id','media_items'),ref('decision_id','binding_decisions'),ref('spatial_export_id','spatial_exports'),CheckConstraint("purpose IN ('blocking','lineart','reference_image','first_frame')",name='purpose'))
    runs=table('intelligent_runs',uid('id',nullable=False),uid('version_id',nullable=False),Column('unit_key',Text,nullable=False),Column('purpose',Text,nullable=False),uid('draft_artifact_id',nullable=False),uid('run_artifact_id',nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),ForeignKeyConstraint(['project_id','version_id','unit_key'],['intelligent_units.project_id','intelligent_units.version_id','intelligent_units.unit_key']),ref('draft_artifact_id','artifact_versions'),ref('run_artifact_id','artifact_versions'))
    tasks=table('intelligent_tasks',uid('id',nullable=False),uid('version_id',nullable=False),uid('dispatch_id',nullable=False),Column('stage',Text,nullable=False),Column('message',Text,nullable=False),Column('skill_id',Text,nullable=False),Column('skill_sha256',Text,nullable=False),Column('status',Text,nullable=False),Column('started_at',DateTime(timezone=True)),Column('host_result',JSONB),Column('error',Text),uid('plan_artifact_id'),uid('output_version_id'),Column('created_by',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),ref('version_id','intelligent_versions'),ref('dispatch_id','role_dispatches'),ref('plan_artifact_id','artifact_versions'),ref('output_version_id','intelligent_versions'),CheckConstraint("stage IN ('assets','blocking','script') AND status IN ('queued','running','result_ready','needs_input','planned','applied','rejected','stopped','failed','submission_unknown')",name='state'))
    decisions=table('intelligent_decisions',uid('id',nullable=False),uid('task_id',nullable=False),Column('outcome',Text,nullable=False),Column('reason',Text,nullable=False),Column('actor',Text,nullable=False),stamp(),PrimaryKeyConstraint('project_id','id'),UniqueConstraint('project_id','task_id'),ref('task_id','intelligent_tasks'),CheckConstraint("outcome IN ('confirm','reject','stop')",name='outcome'))
    tables=(definitions,workflows,versions,assets,units,dependencies,media,runs,tasks,decisions)
    for relation in tables:
        for col in relation.c:
            if col.name.endswith('_id') and col.name not in {'id','project_id'}:Index('ix_'+relation.name+'_'+col.name,relation.c.project_id,col)
    return {r.name:r for r in tables}
